// Return log result
const logResult = $input.item.json;

return {
  logged: true,
  logId: logResult?.id
};

const input = $input.first().json;

return [{
  json: {
    userId: input.userId || input.user?.id || null,
    consultationId: input.consultationId || input.user?.current_consultation_id || null,
    direction: input.direction || 'inbound',
    messageType: input.messageType || 'text',
    content: input.messageContent || input.content || input.userMessage || null,
    whatsappMessageId: input.messageId || input.whatsappMessageId || null,
    metadata: {
      phoneNumber: input.phoneNumber || null,
      rawMessage: input.rawMessage || null,
      timestamp: input.timestamp || new Date().toISOString(),
      contactName: input.contactName || null,
      success: input.success ?? null,
      error: input.error || null
    }
  }
}];

// TD-NEW-026: WF-60 cannot log without a userId (FK NOT NULL).
// Skip silently for callers that don't yet have a userId (e.g., WF-21 welcome before DB insert).
return [{ json: { logged: false, reason: 'no userId — caller did not provide user identification' } }];

